        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Full library counts for the owner. Each problem is counted once (not per topic). */
                        overall: {
                            total: number;
                            solved: number;
                            unsolved: number;
                        };
                        /** @description Every owned topic, including empty topics. Counts reflect the full library, not active list filters. */
                        topics: {
                            total: number;
                            solved: number;
                            unsolved: number;
                            /** Format: uuid */
                            id: string;
                            name: string;
                            /** @description Rounded solved/total*100; 0 when total is 0. */
                            percentComplete: number;
                        }[];
                        /** @description Per-platform counts (catalog slugs + other). Only platforms with at least one problem. */
                        platforms: {
                            total: number;
                            solved: number;
                            unsolved: number;
                            slug: ("codeforces" | "leetcode" | "codechef" | "atcoder" | "hackerrank" | "geeksforgeeks" | "kattis" | "spoj" | "cses" | "beecrowd" | "codewars" | "hackerearth" | "topcoder" | "projecteuler" | "uva" | "aizu") | "other";
                            name: string;
                        }[];
                    };
                };
            };
            "4XX": {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        statusCode: number;
                        code: string;
                        message: string;
                        details?: unknown;
                    };
                };
            };
        };
